#!/usr/bin/env node
/**
 * boundify-graph-to-dirs.js <graph-json-path> [--json] [--dry-run] [--force]
 *
 * Analyzes the graph JSON generated by graphify and proposes a directory tree with safe boundaries.
 * Outputs Dirs-Tree.json (*-BOUNDIFY-Status.json is managed by update-step-status.js).
 *
 * Loads lower-layer modules (boundify-helpers.js, boundify-tree.js) via require
 * and absorbs function signature differences through adapter functions.
 *
 * PX-30: Injects cross-references (crossReferences) of prose-type nodes into each language tree
 * of the output Dirs-Tree.json via boundify-tree.js computeCrossReferences().
 *
 * CLI: boundify-graph-to-dirs.js /path/to/RFC-ROOT-GRAPH.json [--json] [--quiet]
 *
 * Output contract:
 *   Without --json → stdout: .en.md + Markdown analysis + ```json block
 *   With --json    → stdout: JSON only
 *   With --quiet   → Suppress stdout (file output only)
 *   Always writes Dirs-Tree.json to the same directory as the graph (*-BOUNDIFY-Status.json is managed by update-step-status.js)
 *
 * @module boundify-graph-to-dirs
 */

"use strict";

const fs = require("fs");
const path = require("path");

// ============================================================
// Existing Lower-Layer Module Imports
// ============================================================

const helpers = require("./boundify-helpers.js");
const treeBuilder = require("./boundify-tree.js");
const { validateFiles } = require("./validate-dirs-tree-schema.js");
const { createDefaultStatus, atomicWrite } = require("./update-boundify-step-status.js");

// ============================================================
// Constants
// ============================================================

/** Exit code for success */
const EXIT_SUCCESS = 0;
/** Exit code for failure */
const EXIT_FAILURE = 1;

/** Language-specific extensions (reused from boundify-helpers, defined independently to avoid circular references) */
const LANGUAGE_EXTENSIONS = Object.freeze({
  rust: ".rs",
  go: ".go",
  typescript: ".ts",
});

/** 3-section template error — when arguments are missing */
const ERROR_MISSING_ARGS =
  "[ERROR] Insufficient arguments\n" +
  "Cause: A graph JSON file path is required\n" +
  "Action: boundify-graph-to-dirs.js <graph-json-path> [--json] [--quiet] [--dry-run] [--force]";

/** DIRECTIONAL_EDGE_TYPES — reused from helpers */
const DIRECTIONAL_EDGE_TYPES = helpers.DIRECTIONAL_EDGE_TYPES;

// ============================================================
// Error Reporting (3-section template)
// ============================================================

/**
 * Output error in 3-section template format to stderr
 *
 * @param {string} message — Error summary
 * @param {string} cause — Cause
 * @param {string} remedy — Remedy
 * @returns {string} Formatted error text
 */
function reportError(message, cause, remedy) {
  const text = `[ERROR] ${message}\nCause: ${cause}\nAction: ${remedy}`;
  console.error(text);
  return text;
}

// ============================================================
// Usage Display
// ============================================================

/**
 * Display script usage
 */
function printUsage() {
  console.log(`\
boundify-graph-to-dirs.js <graph-json-path> [--json] [--dry-run] [--force]

Arguments:
  <graph-json-path>  Path to the graph JSON file (required)

Flags:
  --json             Output only JSON to stdout
  --quiet            Suppress stdout (file output only)
  --dry-run          Display planned output without writing files
  --force            Overwrite existing files when generating
  --help, -h         Show this help`);
}

// ============================================================
// Argument Parsing
// ============================================================

/**
 * Parse command-line arguments
 *
 * Supports `--graph=<path>` format (canonical) or positional `<path>` format (backward compatibility).
 * When both are specified, `--graph=` takes priority.
 *
 * @param {string[]} [testArgs] — Test argument array (defaults to process.argv when omitted)
 * @returns {{ graphPath: string, graphDir: string, basename: string, flags: { json: boolean, dryRun: boolean, force: boolean, quiet: boolean } }}
 * @throws {never} — Exits via process.exit(EXIT_FAILURE) on failure
 */
function parseArguments(testArgs) {
  const args = testArgs || process.argv.slice(2);

  // If no arguments or --help/-h, show usage and exit
  if (args.length === 0 || args[0] === "--help" || args[0] === "-h") {
    printUsage();
    process.exit(EXIT_SUCCESS);
  }

  // Detect --graph=<path> format and extract path (canonical format)
  const GRAPH_FLAG_PREFIX = "--graph=";
  const graphFlagArg = args.find(function (a) {
    return a.startsWith(GRAPH_FLAG_PREFIX);
  });
  const rawPath = graphFlagArg
    ? graphFlagArg.slice(GRAPH_FLAG_PREFIX.length)
    : args[0];

  // Error on empty string
  if (!rawPath) {
    reportError(
      "Graph file path is empty",
      "--graph= was specified without a path argument",
      "Specify the path in the format: --graph=/path/to/RFC-ROOT-GRAPH.json",
    );
    process.exit(EXIT_FAILURE);
  }

  // Resolve graph path
  const graphPath = path.resolve(rawPath);
  if (!fs.existsSync(graphPath)) {
    reportError(
      `Graph file not found: ${graphPath}`,
      "The specified path does not point to an existing file",
      "Provide the correct path to the graph JSON file" +
        " (e.g. node boundify-graph-to-dirs.js --graph=./RFC-ROOT-GRAPH.json)",
    );
    process.exit(EXIT_FAILURE);
  }

  const flags = {
    json: args.includes("--json"),
    dryRun: args.includes("--dry-run"),
    force: args.includes("--force"),
    quiet: args.includes("--quiet"),
  };

  const graphDir = path.dirname(graphPath);
  const baseName = path.basename(graphPath, path.extname(graphPath));
  // basename: remove -GRAPH suffix if present, otherwise use filename as-is
  const basename = baseName.endsWith("-GRAPH")
    ? baseName.slice(0, -6)
    : baseName;

  return { graphPath, graphDir, basename, flags };
}

// ============================================================
// Graph Loading and Validation
// ============================================================

/**
 * Load a graph JSON file and validate the existence of nodes/edges
 *
 * @param {string} graphPath — Path to the graph JSON file
 * @returns {{ nodes: object[], edges: object[] }} Parsed graph object
 * @throws {never} — Exits via process.exit(EXIT_FAILURE) on failure
 */
function loadGraph(graphPath) {
  let raw;
  try {
    raw = fs.readFileSync(graphPath, "utf-8");
  } catch (e) {
    reportError(
      `Failed to read graph file: ${e.message}`,
      "File I/O error",
      "Verify file permissions and that the file exists",
    );
    process.exit(EXIT_FAILURE);
  }

  let graph;
  try {
    graph = JSON.parse(raw);
  } catch (e) {
    reportError(
      `Failed to parse graph JSON: ${e.message}`,
      "Invalid JSON format",
      "Verify the graph file contains valid JSON" +
        ' (validatable via: node -e "JSON.parse(fs.readFileSync(...))")',
    );
    process.exit(EXIT_FAILURE);
  }

  if (!graph.nodes || !Array.isArray(graph.nodes)) {
    reportError(
      "nodes array not found in graph JSON",
      "Required field nodes is missing",
      "Provide a valid graph JSON generated by /graphify-rfc",
    );
    process.exit(EXIT_FAILURE);
  }

  if (!graph.edges || !Array.isArray(graph.edges)) {
    reportError(
      "edges array not found in graph JSON",
      "Required field edges is missing",
      "Provide a valid graph JSON generated by /graphify-rfc",
    );
    process.exit(EXIT_FAILURE);
  }

  return graph;
}

// ============================================================
// Adapter Functions — Absorbing signature differences between existing lower-layer and RFC §4.2
// ============================================================

/**
 * Adapt P18-1 (boundify-tree.js) buildDirectoryTree
 *
 * PX-25: Injects languageExtensions to replace titleToFileName.
 * File names are generated from node slug + extension.
 *
 * @param {object} graph — Graph object
 * @param {string} lang — Language name ('rust' | 'go' | 'typescript')
 * @returns {{ tree: object|null, nodeToDir: object, files: Array }}
 */
function adaptBuildDirectoryTree(graph, lang) {
  const boundHelpers = {
    languageExtensions: LANGUAGE_EXTENSIONS,
    deduplicateFileNames: helpers.deduplicateFileNames,
    getDeclarationStub: helpers.getDeclarationStub,
  };
  return treeBuilder.buildDirectoryTree(graph, lang, boundHelpers);
}

/**
 * Adapt P17-1 (boundify-helpers.js) projectEdgesToDirectories
 *
 * RFC §4.2 expects projectEdgesToDirectories(graph, nodeToDir) with 2 arguments,
 * but P17-1 implements projectEdgesToDirectories(graphEdges, nodeToDirMap) with 2 arguments.
 * This adapter extracts graph.edges before passing.
 *
 * @param {object} graph — Graph object
 * @param {object} nodeToDir — Node ID → directory path mapping
 * @returns {{ from: string, to: string, type: string, evidence: string }[]}
 */
function adaptProjectEdgesToDirectories(graph, nodeToDir) {
  return helpers.projectEdgesToDirectories(graph.edges || [], nodeToDir);
}

/**
 * Collect the list of actual language values present in the graph
 *
 * Directly reads the language field (single value) of nodes added via PX-24 schema.
 * Does not perform language inference. Nodes without language are ignored.
 * Falls back to graph.mainLanguage if all nodes lack language.
 *
 * @param {{ mainLanguage?: string, nodes: object[] }} graph — Graph object
 * @returns {string[]} Unique array of language values in use (at least 1)
 */
function collectLanguagesFromGraph(graph) {
  const languageSet = new Set();
  for (const node of (graph.nodes || [])) {
    if (node.language && typeof node.language === "string") {
      languageSet.add(node.language);
    }
  }
  if (languageSet.size === 0 && graph.mainLanguage && typeof graph.mainLanguage === "string") {
    languageSet.add(graph.mainLanguage);
  }
  return Array.from(languageSet);
}

// ============================================================
// Dirs-Tree.json Construction
// ============================================================

/**
 * Aggregate count per kind in the graph
 *
 * @param {{ nodes: object[] }} graph — Graph object
 * @returns {object} kind → count map
 */
function countKinds(graph) {
  const counts = {};
  for (const node of graph.nodes) {
    const kind = node.kind || "unknown";
    counts[kind] = (counts[kind] || 0) + 1;
  }
  return counts;
}

/**
 * Aggregate count per edge type in the graph
 *
 * @param {{ edges: object[] }} graph — Graph object
 * @returns {object} edge type → count map
 */
function countEdgeTypes(graph) {
  const counts = {};
  for (const edge of graph.edges) {
    counts[edge.type] = (counts[edge.type] || 0) + 1;
  }
  return counts;
}

/**
 * Collect all directory paths from the directory tree
 *
 * Collected paths match the format expected by validate-dirs-tree-schema.js.
 * The tree root is "src", child node paths become "src/config", etc.
 *
 * @param {object|null} tree — Root node of the directory tree
 * @returns {Set<string>} Set of directory paths
 */
function collectDirectoryPaths(tree) {
  const paths = new Set();
  if (!tree) return paths;

  function walk(node, currentPath) {
    if (node.type === "directory") {
      const fullPath = currentPath ? currentPath + "/" + node.name : node.name;
      paths.add(fullPath);
      if (node.children) {
        for (const child of node.children) {
          walk(child, fullPath);
        }
      }
    }
  }

  walk(tree, "");
  return paths;
}

/**
 * Resolve the full tree path from a directory name
 *
 * Targets only directory names to avoid matching file names.
 * If multiple directories have the same name, uses the first one found.
 *
 * @param {Set<string>} dirPaths — Return value from collectDirectoryPaths
 * @param {string} dirName — Directory name to resolve (e.g. "config")
 * @returns {string|null} Full path (e.g. "src/config"), or null if not found
 */
function resolveDirNameToPath(dirPaths, dirName) {
  for (const dirPath of dirPaths) {
    // Check if the last path segment matches dirName
    const segments = dirPath.split("/");
    const lastSegment = segments[segments.length - 1];
    if (lastSegment === dirName) {
      return dirPath;
    }
  }
  return null;
}

/**
 * Determine output file paths
 *
 * Outputs 2 files (Dirs-Tree.json, Status.json) to the same directory as the graph JSON.
 * basename is the base name with -GRAPH suffix removed.
 *
 * @param {string} graphDir — Graph directory
 * @param {string} basename — Base name (with -GRAPH removed)
 * @returns {{ dirsTreePath: string, statusPath: string }}
 */
function resolveOutputPaths(graphDir, basename) {
  return {
    dirsTreePath: path.join(graphDir, `${basename}-Dirs-Tree.json`),
    statusPath: path.join(graphDir, `${basename}-BOUNDIFY-Status.json`),
  };
}

// ============================================================
// Main Entry Point
// ============================================================

/**
 * Main Entry Point. Integrates the entire process
 *
 * Process flow:
 *   1. Argument Parsing → parseArguments
 *   2. Graph Loading → loadGraph
 *   3. Collect languages present in graph → collectLanguagesFromGraph
 *   4. Per-language tree generation and dependency analysis
 *   5. Dirs-Tree.json Construction
 *   6. Schema Validation → validateFiles
 *   7. Write 3 files
 *   8. Stdout 3-way branch (--json / --quiet / default)
 *
 * @param {string[]} [testArgs] — Test argument array
 */
function main(testArgs) {
  // ---- Step 1-2: Argument parsing and graph loading ----
  const { graphPath, graphDir, basename, flags } = parseArguments(testArgs);
  const graph = loadGraph(graphPath);

  // ---- Step 3: Collect languages present in graph ----
  // Directly read the language field (single value) from the PX-24 schema.
  // Nodes without language are ignored.
  const languages = collectLanguagesFromGraph(graph);

  // ---- Step 4: Per-language tree generation and dependency analysis ----
  const trees = {};
  const allDependencyDirections = {};
  const allWarnings = [];

  for (const lang of languages) {
    // 4-a: Directory tree generation (via adapter)
    const { tree, nodeToDir, nodeIdToFilePath } = adaptBuildDirectoryTree(graph, lang);
    trees[lang] = tree;

    // 4-a2: Cross-reference calculation (PX-30: associate prose node design info with connected files)
    if (tree && graph) {
      tree.crossReferences = treeBuilder.computeCrossReferences(graph, nodeToDir, nodeIdToFilePath);
    }

    // 4-b: Edge projection (via adapter)
    const dirEdges = adaptProjectEdgesToDirectories(graph, nodeToDir);

    // Record dependency direction (resolve dir name → full path)
    const dirPaths = collectDirectoryPaths(tree);
    allDependencyDirections[lang] = dirEdges.map(function (edge) {
      return {
        from: resolveDirNameToPath(dirPaths, edge.from) || edge.from,
        to: resolveDirNameToPath(dirPaths, edge.to) || edge.to,
        rule: edge.from + " → " + edge.to + " (" + edge.evidence + ")",
      };
    });

    // 4-c: Cyclic dependency detection
    const cycles = helpers.tarjanSCC(dirEdges);
    for (const cycle of cycles) {
      const cyclePath = cycle.cycle.join(" → ");
      allWarnings.push({
        cycle: cycle.cycle,
        language: lang,
        message:
          `Circular dependency detected: ${cyclePath} (${lang})\n` +
          `This may be a design-level issue. Follow these steps to resolve:\n` +
          `\n` +
          `  1. Examine each edge type (depends_on, refines, etc.) in the cycle to determine whether the semantics truly require bidirectional dependency\n` +
          `\n` +
          `  2. If genuine bidirectional dependency is necessary (e.g. mutually referencing state machines), you may accept it as a design choice.\n` +
          `     In that case, the warning can remain recorded as a known constraint and proceed to the next step\n` +
          `\n` +
          `  3. For edges that can be made unidirectional, fix them with crud.js:\n` +
          `     node .claude/scripts/rfc-graph/crud.js --graph="<graphPath>" delete-edges --file=_remove.json\n` +
          `     node .claude/scripts/rfc-graph/crud.js --graph="<graphPath>" create-edges --file=_add.json\n` +
          `\n` +
          `  4. If the cycle is a design error, check the source RFC to identify the correct dependency direction and fix edge definitions directly with crud.js\n` +
          `\n` +
          `  5. After fixing, re-run this script to confirm the cycle is resolved, then run verify-graph-integrity.js for regression checks\n` +
          `\n` +
          `Note: Avoid deleting or reversing edges without considering their semantics, as this degrades graph quality. Always confirm the meaning of each edge before modifying`,
      });
    }
  }

  // ---- Step 5: Dirs-Tree.json Construction ----
  const dirsTree = {
    schemaVersion: "1.0",
    generatedAt: new Date().toISOString(),
    sourceGraph: graphPath,
    sourceFile: graph.sourceFile || '',
    analysis: {
      nodeCount: graph.nodes.length,
      edgeCount: graph.edges.length,
      kindCounts: countKinds(graph),
      edgeTypeCounts: countEdgeTypes(graph),
      circularDependencies: allWarnings.length > 0 ? allWarnings : undefined,
    },
    trees: trees,
    dependencyDirections: allDependencyDirections,
    warnings: allWarnings,
  };

  // ---- Step 6: Schema validation (file-based validation after writing) ----
  const outputPaths = resolveOutputPaths(graphDir, basename);

  // --dry-run mode: skip file writing and validation
  if (flags.dryRun) {
    if (flags.json) {
      console.log(JSON.stringify(dirsTree, null, 2));
    } else if (!flags.quiet) {
      const report = treeBuilder.generateReport(graph, dirsTree, "rust");
      const jsonBlock = JSON.stringify(dirsTree, null, 2);
      console.log(helpers.SAFE_BOUNDARIES_EN_TEXT);
      console.log("");
      console.log(report);
      console.log("");
      console.log("```json");
      console.log(jsonBlock);
      console.log("```");
    }
    return;
  }

  // First write Dirs-Tree.json (needed for validation)
  fs.writeFileSync(
    outputPaths.dirsTreePath,
    JSON.stringify(dirsTree, null, 2),
    "utf-8",
  );

  // Validate the written file with validateFiles
  const validationResult = validateFiles(outputPaths.dirsTreePath, graphPath);
  if (!validationResult.ok) {
    // On validation failure, delete the written file and exit
    try {
      fs.unlinkSync(outputPaths.dirsTreePath);
    } catch (_) {
      /* Ignore deletion failure */
    }
    reportError(
      "Dirs-Tree.json schema validation failed",
      validationResult.errors.join("\n"),
      "Check validate-dirs-tree-schema.js output and fix accordingly",
    );
    process.exit(EXIT_FAILURE);
  }

  // Write BOUNDIFY-Status.json in the correct format
  // Borrow createDefaultStatus from update-boundify-step-status.js to
  // share the schema definition (avoiding risk of dispersed schema definitions)
  const statusData = createDefaultStatus(outputPaths.statusPath);
  statusData.currentStep = 2;
  statusData.steps["0"] = "done";
  statusData.steps["1"] = "done";
  statusData.steps["2"] = "running";
  atomicWrite(outputPaths.statusPath, JSON.stringify(statusData, null, 2));

  // ---- Step 7: Stdout 3-way branch ----
  if (flags.json) {
    // --json: stdout only JSON
    console.log(JSON.stringify(dirsTree, null, 2));
  } else if (!flags.quiet) {
    // Default: .en.md + Markdown + JSON block
    const report = treeBuilder.generateReport(graph, dirsTree, "rust");
    const jsonBlock = JSON.stringify(dirsTree, null, 2);
    console.log(helpers.SAFE_BOUNDARIES_EN_TEXT);
    console.log("");
    console.log(report);
    console.log("");
    console.log("```json");
    console.log(jsonBlock);
    console.log("```");
  }
  // --quiet: completely suppress stdout (file output only)
}

// ============================================================
// Entry Point
// ============================================================

if (require.main === module) {
  main();
}

module.exports = {
  main,
  parseArguments,
  loadGraph,
  adaptBuildDirectoryTree,
  adaptProjectEdgesToDirectories,
  collectLanguagesFromGraph,
  reportError,
  printUsage,
  countKinds,
  countEdgeTypes,
  resolveOutputPaths,
  collectDirectoryPaths,
  resolveDirNameToPath,
  LANGUAGE_EXTENSIONS,
};
